import React, { useState, useEffect, useRef } from 'react';
import './App.css';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import { useAuth } from './hooks/useAuth';
import { User, Lock, Eye, EyeOff, AlertCircle } from 'lucide-react';

const DEFAULT_USERNAME = process.env.REACT_APP_ADMIN_USERNAME || 'admin';
const DEFAULT_PASSWORD = process.env.REACT_APP_ADMIN_PASSWORD || 'admin123';

function App() {
  const { user, login, logout, isAuthenticated } = useAuth();
  const [loginError, setLoginError] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [rememberMe, setRememberMe] = useState(false);
  const [username, setUsername] = useState(DEFAULT_USERNAME);
  const [password, setPassword] = useState(DEFAULT_PASSWORD);
  const usernameRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (!isAuthenticated && usernameRef.current && !DEFAULT_USERNAME) {
      usernameRef.current.focus();
    }
  }, [isAuthenticated]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoginError('');
    setIsLoading(true);

    const credentials = {
      username: username.trim(),
      password,
    };

    if (!credentials.username || !credentials.password) {
      setLoginError('Please enter both username and password.');
      setIsLoading(false);
      return;
    }

    const success = await login(credentials);
    setIsLoading(false);

    if (!success) {
      setLoginError('Invalid credentials. Please check and try again.');
    }
  };

  if (!isAuthenticated) {
    return (
      <div className="login-page">
        <div className="login-container" role="main">

          {/* Heading — no logo */}
          <header className="login-brand">
            <h1>Admin Portal</h1>
            <p>Sign in to continue to your dashboard.</p>
          </header>

          {/* Error */}
          {loginError && (
            <div
              id="login-error"
              className="login-error"
              role="alert"
              aria-live="assertive"
            >
              <span className="login-error-icon">
                <AlertCircle size={15} />
              </span>
              {loginError}
            </div>
          )}

          {/* Form */}
          <form
            className="login-form"
            onSubmit={handleLogin}
            noValidate
            aria-label="Admin sign-in"
            aria-describedby={loginError ? 'login-error' : undefined}
          >
            {/* Username */}
            <div className="form-group">
              <label className="form-label" htmlFor="username">
                Username
              </label>
              <div className="input-wrapper">
                <span className="input-icon-left" aria-hidden="true">
                  <User size={16} />
                </span>
                <input
                  id="username"
                  ref={usernameRef}
                  className="form-input"
                  type="text"
                  name="username"
                  value={username}
                  onChange={e => setUsername(e.target.value)}
                  placeholder="Enter your username"
                  autoComplete="username"
                  spellCheck={false}
                  autoCapitalize="none"
                  required
                  disabled={isLoading}
                  aria-required="true"
                />
              </div>
            </div>

            {/* Password */}
            <div className="form-group">
              <label className="form-label" htmlFor="password">
                Password
              </label>
              <div className="input-wrapper">
                <span className="input-icon-left" aria-hidden="true">
                  <Lock size={16} />
                </span>
                <input
                  id="password"
                  className="form-input with-action"
                  type={showPassword ? 'text' : 'password'}
                  name="password"
                  value={password}
                  onChange={e => setPassword(e.target.value)}
                  placeholder="Enter your password"
                  autoComplete="current-password"
                  required
                  disabled={isLoading}
                  aria-required="true"
                />
                <button
                  type="button"
                  className="input-action-btn"
                  onClick={() => setShowPassword(v => !v)}
                  aria-label={showPassword ? 'Hide password' : 'Show password'}
                  disabled={isLoading}
                >
                  {showPassword
                    ? <EyeOff size={16} />
                    : <Eye size={16} />}
                </button>
              </div>
            </div>

            {/* Remember me + Forgot password */}
            <div className="login-row">
              <label className="remember-label">
                <input
                  type="checkbox"
                  checked={rememberMe}
                  onChange={e => setRememberMe(e.target.checked)}
                  disabled={isLoading}
                />
                Remember me
              </label>
              <button
                type="button"
                className="forgot-link"
                onClick={() => alert('Contact your system administrator to reset your password.')}
                disabled={isLoading}
              >
                Forgot password?
              </button>
            </div>

            {/* Submit */}
            <button
              id="login-submit-btn"
              className="btn-primary"
              type="submit"
              disabled={isLoading}
              aria-busy={isLoading}
            >
              {isLoading ? (
                <>
                  <span className="login-spinner" aria-hidden="true" />
                  Signing in…
                </>
              ) : (
                'Sign in'
              )}
            </button>
          </form>

          <p className="login-footer-note">
            Authorised personnel only · All activity is monitored and logged
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="App">
      <Sidebar user={user} onLogout={logout} />
      <main className="main-content" id="main-content" tabIndex={-1}>
        <Dashboard />
      </main>
    </div>
  );
}

export default App;
